import { describe, expect, it } from 'vitest';
import { computeAutocorrelation } from '../../src/timeseries/acf';
import { computeADF } from '../../src/timeseries/adf';
import {
  logReturn,
  percentReturn,
  simpleDifference,
  simpleMovingAverage,
} from '../../src/timeseries/transforms';
import { loadFixture } from '../fixtures/loadFixture';

// Validates the time-series engine against committed statsmodels / pandas
// references (generated by tests/fixtures/generate_fixtures.py). This is the
// part of the engine that previously had no external-reference validation.

interface SeriesExpected {
  observations: number;
  maxLag: number;
  acf: number[];
  pacf: number[];
  ljungBox: Array<{ lag: number; qStatistic: number; pValue: number }>;
  adfLag: number | null;
  adfStatistic: number | null;
}

interface SeriesFixture {
  data: number[];
  expected: SeriesExpected;
}

const fx = loadFixture<{ series: Record<string, SeriesFixture> }>(
  'time_series_statsmodels.json'
);

function closeTo(actual: number, expected: number, tol: number): boolean {
  return Math.abs(actual - expected) <= tol * Math.max(1, Math.abs(expected));
}

describe('ACF validated against statsmodels (biased estimator)', () => {
  for (const [name, series] of Object.entries(fx.series)) {
    it(`matches ACF for the ${name} series`, () => {
      const result = computeAutocorrelation(series.data, series.expected.maxLag);
      const acf = result.rows.map(row => row.autocorrelation);
      expect(acf).toHaveLength(series.expected.acf.length);
      acf.forEach((value, index) => {
        expect(closeTo(value, series.expected.acf[index], 1e-9)).toBe(true);
      });
      // ACF property: lag-0 normalisation means lag-1 is the first reported row.
      expect(result.rows[0].lag).toBe(1);
    });
  }
});

describe('PACF validated against statsmodels (Levinson-Durbin biased, method=ldb)', () => {
  for (const [name, series] of Object.entries(fx.series)) {
    it(`matches PACF for the ${name} series`, () => {
      const result = computeAutocorrelation(series.data, series.expected.maxLag);
      const pacf = result.pacf.map(row => row.partialAutocorrelation);
      expect(pacf).toHaveLength(series.expected.pacf.length);
      pacf.forEach((value, index) => {
        expect(closeTo(value, series.expected.pacf[index], 1e-8)).toBe(true);
      });
    });
  }
});

describe('Ljung-Box validated against statsmodels.acorr_ljungbox', () => {
  for (const [name, series] of Object.entries(fx.series)) {
    it(`matches Ljung-Box Q and p-values for the ${name} series`, () => {
      const result = computeAutocorrelation(series.data, series.expected.maxLag);
      for (const expected of series.expected.ljungBox) {
        const row = result.ljungBox.find(r => r.lag === expected.lag);
        expect(row, `expected a Ljung-Box row for lag ${expected.lag}`).toBeDefined();
        expect(closeTo(row!.qStatistic, expected.qStatistic, 1e-7)).toBe(true);
        expect(closeTo(row!.pValue, expected.pValue, 1e-6)).toBe(true);
      }
    });
  }
});

describe('ADF statistic validated against statsmodels.adfuller (regression=c, fixed lag)', () => {
  for (const [name, series] of Object.entries(fx.series)) {
    if (series.expected.adfLag === null || series.expected.adfStatistic === null) continue;
    it(`matches the ADF t-statistic for the ${name} series`, () => {
      const result = computeADF(series.data, series.expected.adfLag!);
      expect(result.available).toBe(true);
      if (result.available) {
        expect(result.lag).toBe(series.expected.adfLag);
        expect(closeTo(result.statistic, series.expected.adfStatistic!, 1e-6)).toBe(true);
      }
    });
  }
});

describe('ADF qualitative behaviour', () => {
  it('flags a random walk as non-stationary and an AR(1) as more stationary', () => {
    const rw = computeADF(fx.series.random_walk.data, 1);
    const ar = computeADF(fx.series.ar1_phi_0_6.data, 1);
    expect(rw.available && ar.available).toBe(true);
    if (rw.available && ar.available) {
      // A stationary AR(1) should sit further into the rejection (more negative) region
      // than a random walk under the same lag specification.
      expect(ar.statistic).toBeLessThan(rw.statistic);
    }
  });
});

describe('Series transforms validated against pandas / numpy', () => {
  const tf = loadFixture<{
    data: { levels: number[] };
    expected: {
      simpleDifference: Array<number | null>;
      percentReturn: Array<number | null>;
      logReturn: Array<number | null>;
      simpleMovingAverage_window3: Array<number | null>;
    };
  }>('transforms_pandas.json');

  function expectMatches(actual: Array<number | null>, expected: Array<number | null>): void {
    expect(actual).toHaveLength(expected.length);
    actual.forEach((value, index) => {
      const want = expected[index];
      if (want === null) {
        expect(value).toBeNull();
      } else {
        expect(value).not.toBeNull();
        expect(closeTo(value as number, want, 1e-9)).toBe(true);
      }
    });
  }

  it('matches pandas Series.diff', () => {
    expectMatches(simpleDifference(tf.data.levels), tf.expected.simpleDifference);
  });

  it('matches pandas pct_change * 100', () => {
    expectMatches(percentReturn(tf.data.levels), tf.expected.percentReturn);
  });

  it('matches numpy log returns', () => {
    expectMatches(logReturn(tf.data.levels), tf.expected.logReturn);
  });

  it('matches pandas rolling(3).mean()', () => {
    expectMatches(simpleMovingAverage(tf.data.levels, 3), tf.expected.simpleMovingAverage_window3);
  });

  it('produces difference output of length n (null-padded at index 0)', () => {
    const diff = simpleDifference(tf.data.levels);
    expect(diff).toHaveLength(tf.data.levels.length);
    expect(diff[0]).toBeNull();
    expect(diff.slice(1).every(v => v !== null)).toBe(true);
  });
});
